/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <=i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline symmetric matrix-matrix kernel, directly matching the
# PolyBench implementation.
@proc
def kernel_symm_unoptimized(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    for i in seq(0, m):
        for j in seq(0, n):
            temp2: DATA_TYPE
            temp2 = 0
            for k in seq(0, i):
                # Accumulate contributions into the symmetric part.
                C[k, j] += alpha * B[i, j] * A[i, k]
                temp2 += B[k, j] * A[i, k]
            # Final update of C(i,j) including beta scaling and diagonal term.
            C[i, j] = beta * C[i, j] + alpha * B[i, j] * A[i, i] + alpha * temp2


# ---------------------------------------------------------------------------
# Scheduling for performance
# ---------------------------------------------------------------------------

kernel_symm_scheduled = kernel_symm_unoptimized

# 1) Reorder the outer loops so that j is the outermost loop.
#    This exposes column-wise parallelism and lets us stage entire
#    columns of B and C at once.
kernel_symm_scheduled = reorder_loops(kernel_symm_scheduled, "i j")

# 2) Stage a full column of B into a contiguous temporary buffer B_col.
#    Each j-iteration only touches B[0:m, j], so we can load that window
#    once, reuse it many times in the inner loops, and avoid repeatedly
#    strided accesses to B in DRAM.
j_loop = kernel_symm_scheduled.find_loop("for j in _:_")
kernel_symm_scheduled = stage_mem(
    kernel_symm_scheduled,
    j_loop.body(),
    "B[0:m, j]",
    "B_col",
)

# 3) Stage the corresponding column of C into a temporary C_col.
#    All reads and writes to C for a given j are confined to C[0:m, j].
#    By staging this column, we turn strided accesses into dense accesses
#    on C_col and only commit the updated column back to DRAM once.
j_loop = kernel_symm_scheduled.find_loop("for j in _:_")
kernel_symm_scheduled = stage_mem(
    kernel_symm_scheduled,
    j_loop.body(),
    "C[0:m, j]",
    "C_col",
)

# Simplify after the staging transformations to clean up index arithmetic.
kernel_symm_scheduled = simplify(kernel_symm_scheduled)

# 4) Parallelize the outer j loop.
#    Different j-iterations operate on disjoint columns of B and C,
#    so they are independent and can safely be executed in parallel.
#    This is lowered to an OpenMP parallel for in the generated C.
j_loop = kernel_symm_scheduled.find_loop("for j in _:_")
kernel_symm_scheduled = parallelize_loop(kernel_symm_scheduled, j_loop)

# Final cleanup pass.
kernel_symm_scheduled = simplify(kernel_symm_scheduled)

# Export the optimized procedure under the expected name.
kernel_symm = kernel_symm_scheduled
