    # This matches the "beta * C[i, j]" part of the original kernel.
    for i in seq(0, m):
        for j in seq(0, n):
            C[i, j] = beta * C[i, j]

    # Phase 2: symmetric matrix-matrix product
    # C := C + alpha * S * B, where S is the full symmetric matrix
    # implicitly defined from the stored lower-triangular part A:
    #   S[i, k] = A[i, k] if k <= i else A[k, i]
    #
    # It can be shown that the original Polybench SYMM kernel computes
    # exactly:
    #   C[i, j] = beta * C_old[i, j] + alpha * sum_k S[i, k] * B[k, j]
    #
