# on smaller column blocks that fit better in cache.
kernel_symm = divide_loop(kernel_symm, "j #1", J_BLOCK, ["jo", "ji"], tail="guard")

# Parallelize the outer i loop of the symmetric product. Each row of C
# is updated independently in this phase, so the loop is embarrassingly
# parallel.
kernel_symm = parallelize_loop(kernel_symm, "i #1")

# Parallelize the i loop of the scaling phase as well.
kernel_symm = parallelize_loop(kernel_symm, "i #0")
