from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable tile size for the column dimension (j).
TILE_J = 64

@proc
def kernel_symm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Phase 1: scale C by beta and add the diagonal contribution
    # alpha * B * diag(A).  Each (i, j) is updated exactly once here.
    for i in seq(0, m):
        # Load A[i, i] once per row to reduce redundant memory traffic.
        a_ii: DATA_TYPE
        a_ii = A[i, i]
        for j in seq(0, n):
            C[i, j] = beta * C[i, j] + alpha * B[i, j] * a_ii

    # Phase 2: accumulate the strictly lower-triangular part of A,
    # exploiting symmetry.  For each pair (i, k) with k < i we update
    # both rows i and k:
    #
    #   C[k, j] += alpha * B[i, j] * A[i, k]
    #   C[i, j] += alpha * B[k, j] * A[i, k]
    #
    # This is algebraically equivalent to the reference PolyBench SYMM
    # kernel, but restructured to:
    #   - keep j as the innermost index for contiguous accesses to
    #     rows of B and C (better cache and vectorization),
    #   - avoid the inner scalar accumulator temp2 by distributing
    #     its contributions directly into C[i, j].
